// The versions the page offers to build.
//
// `versions.json` is generated by `.github/workflows/pages.yml` and served next to
// the page. It lists two kinds of payload:
//
//   * every release that carries one (`firmware-payload-<board>.tar.gz` uploaded by
//     `.github/workflows/player-package.yml` when a tag is pushed), newest first;
//   * the build this deployment was made from, always last, for someone who wants
//     the tip of `main` rather than a release.
//
// A release's payload is copied into the site by the same workflow, because
// GitHub's release assets do not answer with `Access-Control-Allow-Origin` and a
// browser cannot fetch them from another origin. The file is still the one the
// release published; the copy is a mirror, and `sha256` is checked before anything
// is unpacked.
//
//   {"format": 1, "versions": [
//     {"label": "0.5.0", "version": "1.3.0/0.5.0", "stamp": "241120240140",
//      "published": "2026-11-23T10:00:00Z", "release": true,
//      "player": {"url": "payload/0.5.0.player.tar.gz", "size": 3145728, "sha256": "..."},
//      "assets": {"url": "payload/blobs/assets-3f9c1d2a4b5c.tar.gz", "size": 23068672, "sha256": "..."}},
//     {"label": "main", "version": "1.3.0/#abcdef0", "stamp": "...", "published": null,
//      "release": false,
//      "player": {"url": "payload/current.player.tar.gz", ...},
//      "assets": {"url": "payload/blobs/assets-3f9c1d2a4b5c.tar.gz", ...}}
//   ]}

export class VersionsError extends Error {}

/**
 * Validates and returns the list.
 *
 * An empty list is a legitimate state: the site publishes only the newest tag that
 * carries a payload, and until the first such release exists there is nothing to
 * offer. The page says so rather than pretending.
 */
export function parseVersions(data) {
  if (data?.format !== 1) throw new VersionsError(`versions.json format ${data?.format} is newer than this page`);
  const versions = Array.isArray(data.versions) ? data.versions : [];
  for (const version of versions) {
    if (!version?.label) throw new VersionsError('an entry in versions.json has no label');
    const single = Boolean(version.url);
    const split = Boolean(version.player?.url && version.assets?.url);
    if (!single && !split) throw new VersionsError(`version ${version.label} names no payload`);
  }
  return versions;
}

export async function loadVersions(url, options = {}) {
  const fetchImpl = options.fetch || fetch;
  const response = await fetchImpl(url, { cache: 'no-cache' });
  if (!response.ok) throw new VersionsError(`cannot fetch ${url}: HTTP ${response.status}`);
  return parseVersions(await response.json());
}

/** The entry to build with: the released one, or the only one there is. */
export function defaultVersion(versions) {
  return versions.find((version) => version.release) ?? versions[versions.length - 1];
}

/**
 * What the selector shows: the image's version, which is
 * `<vendor firmware>/<the port's own version>` -- "1.3.0/0.5.0" for a release, or
 * "1.3.0/#57b1aea" for a build off a commit. The tag alone ("0.5.0") would hide
 * which vendor image the payload was built on, and that is the half the user's
 * own firmware decides.
 */
export function versionLabel(version) {
  const name = version.version ?? version.label;
  const built = version.published ? new Date(version.published).toISOString().slice(0, 10) : 'this page';
  const size = payloadSize(version);
  return [name, built, size ? `${(size / 1048576).toFixed(0)} MB` : ''].filter(Boolean).join(' · ');
}

/** What a version costs to download, over both halves. */
export function payloadSize(version) {
  if (version.url) return version.size ?? 0;
  return (version.player?.size ?? 0) + (version.assets?.size ?? 0);
}
